function validate([s1, s2]) {
  if (s1.length < 1 || s1.length > 100000) return 's1 needs 1 to 10^5 letters.';
  if (s2.length !== s1.length) return 's1 and s2 must have the same length.';
  if (!/^[a-z]+$/.test(s1) || !/^[a-z]+$/.test(s2)) return 'Use only lowercase English letters.';
  return null;
}

