function checkIfCanBreak(s1, s2) {
  const sorted1 = s1.split('').sort();
  const sorted2 = s2.split('').sort();
  let firstBreaks = true;
  let secondBreaks = true;

  for (let i = 0; i < sorted1.length; i++) {
    if (sorted1[i] < sorted2[i]) {
      firstBreaks = false;
    }
    if (sorted1[i] > sorted2[i]) {
      secondBreaks = false;
    }
  }
  return firstBreaks || secondBreaks;
}

