function checkIfCanBreak(s1, s2) {
  // x can break y exactly when, for every letter c, x has no more letters <= c than y does.
  const atMost = (s, c) => [...s].filter(ch => ch <= c).length;
  let oneWins = true, twoWins = true;
  for (const c of 'abcdefghijklmnopqrstuvwxyz') {
    const a = atMost(s1, c), b = atMost(s2, c);
    if (a > b) oneWins = false;
    if (b > a) twoWins = false;
  }
  return oneWins || twoWins;
}

