function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' ? 26 : 1 + Math.floor(rand() * 5);
  const base = Math.floor(rand() * (26 - span + 1));
  const letter = code => String.fromCharCode(97 + code);
  const codes = Array.from({ length: n }, () => base + Math.floor(rand() * span));
  const s1 = codes.map(letter).join('');
  const mode = rand();
  let s2;
  if (mode < 0.4) {
    // Lower some letters of s1 and shuffle, so s1 breaks s2.
    const lowered = codes.map(c => rand() < 0.4 ? Math.max(0, c - Math.floor(rand() * 4)) : c);
    for (let i = lowered.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [lowered[i], lowered[j]] = [lowered[j], lowered[i]]; }
    s2 = lowered.map(letter).join('');
  } else {
    s2 = Array.from({ length: n }, () => letter(base + Math.floor(rand() * span))).join('');
  }
  return rand() < 0.5 ? [s1, s2] : [s2, s1];
}
